:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --cell: #2a2a4a;
  --food: #e94560;
  --snake: #4ecca3;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

h1 {
  font-size: 1.5rem;
  color: var(--primary);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.125rem;
  font-weight: 600;
  background: var(--accent);
  padding: 6px 16px;
  border-radius: 20px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  background: var(--bg);
  border-radius: 8px;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  display: none;
}

.overlay-content h2 {
  font-size: 1.5rem;
  margin-bottom: 12px;
  color: var(--primary);
}

.overlay-content p {
  margin-bottom: 20px;
  line-height: 1.6;
  color: var(--text);
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  padding: 10px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  font-family: inherit;
}

.btn:hover {
  background: #1a4a7a;
  border-color: var(--primary);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #c73550;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .btn {
  flex: 1;
  max-width: 200px;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .overlay-content h2 {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayMessage = document.getElementById('overlayMessage');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;

  let snake, direction, nextDirection, food, score, gameOver, paused, gameLoop;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    gameOver = false;
    paused = true;
    scoreEl.textContent = '0';
    placeFood();
    draw();
    updateOverlay();
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines (subtle)
    ctx.strokeStyle = '#2a2a4a';
    ctx.lineWidth = 0.5;
    for (let i = 1; i < GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(canvas.width, i * CELL_SIZE);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL_SIZE + 1, food.y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);

    // Draw snake
    snake.forEach((segment, index) => {
      ctx.fillStyle = index === 0 ? '#4ecca3' : '#3ba882';
      ctx.fillRect(segment.x * CELL_SIZE + 1, segment.y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
    });
  }

  function update() {
    if (paused || gameOver) return;

    direction = nextDirection;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Wall collision
    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      endGame();
      return;
    }

    // Self collision
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    paused = false;
    clearInterval(gameLoop);
    showOverlay('Game Over', 'Your score: ' + score + '<br>Press Restart to play again.', 'Restart Game');
  }

  function showOverlay(title, message, buttonText) {
    overlayTitle.textContent = title;
    overlayMessage.innerHTML = message;
    startBtn.textContent = buttonText;
    overlay.classList.remove('hidden');
  }

  function updateOverlay() {
    if (gameOver) return;
    if (paused) {
      showOverlay('How to Play', 'Use arrow keys to move the snake.<br>Eat the food to grow and score points.<br>Don\'t hit the walls or yourself!', 'Start Game');
    } else {
      overlay.classList.add('hidden');
    }
  }

  function startGame() {
    if (gameOver) {
      init();
    }
    paused = false;
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    clearInterval(gameLoop);
    gameLoop = setInterval(update, 150);
  }

  function togglePause() {
    if (gameOver) return;
    paused = !paused;
    if (paused) {
      clearInterval(gameLoop);
      pauseBtn.textContent = 'Resume';
      showOverlay('Paused', 'Press Resume or the Start button to continue.', 'Resume');
    } else {
      pauseBtn.textContent = 'Pause';
      overlay.classList.add('hidden');
      gameLoop = setInterval(update, 150);
    }
  }

  function restartGame() {
    clearInterval(gameLoop);
    init();
    paused = true;
    pauseBtn.textContent = 'Pause';
    updateOverlay();
  }

  // Event listeners
  document.addEventListener('keydown', function (e) {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (paused || gameOver) return;
      if (key === 'ArrowUp' && direction.y === 0) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y === 0) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x === 0) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x === 0) nextDirection = { x: 1, y: 0 };
    } else if (key === ' ' || key === 'Space') {
      e.preventDefault();
      if (gameOver) return;
      togglePause();
    }
  });

  startBtn.addEventListener('click', function () {
    if (gameOver) {
      restartGame();
    }
    startGame();
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restartGame);

  // Initialize
  init();
})();
